int TBAnimTableCount(void) { return (int)(sizeof(kTables) / sizeof(kTables[0])); }
const TBAnimTable *TBAnimTables(void) { return kTables; }

const TBAnimTable *TBAnimTableForClass(const char *className) {
    if (!className) return NULL;
    for (int i = 0; i < TBAnimTableCount(); i++) {
        if (strcmp(kTables[i].name, className) == 0) return &kTables[i];
    }
    return NULL;
}
